"""
궁합 API — 4축 분석.

Auth + gating:
- 인증 필수 (401 if missing)
- 접근 조건: user.tier == 'premium' OR has_addon('compatibility')
- 그 외 403
"""
import logging

from fastapi import APIRouter, Depends, HTTPException

from app.engine.calculator import calculate_saju
from app.engine.compatibility import compute_compatibility
from app.semantic.tagger import build_semantic_profile
from app.services.compatibility_writer import write_compatibility
from app.auth.dependencies import get_current_user
from app.auth.repository import get_repository
from app.schemas.compatibility import CompatibilityRequest, CompatibilityResponse
from app.api.errors import format_dst_error
from app.engine.time_correction import DSTAmbiguousError, DSTGapError


logger = logging.getLogger(__name__)
router = APIRouter()


def _can_access_compat(user: dict) -> bool:
    if user.get("tier") == "premium":
        return True
    return get_repository().has_addon(user["id"], "compatibility")


def _build_profile(payload) -> dict:
    """SajuRequest → semantic profile. target_year 은 궁합에 무관하므로 미사용."""
    result = calculate_saju(
        birth_date=payload.birth_date,
        birth_time=payload.birth_time,
        birth_time_mode=payload.birth_time_mode,
        timezone_str=payload.timezone_str,
        longitude=payload.longitude,
        correction_mode=payload.correction_mode,
        jasi_boundary=payload.jasi_boundary,
        gender=payload.gender,
        lang=payload.lang,
        dst_fold=payload.dst_fold,
        birth_location=payload.birth_location,
    )
    return build_semantic_profile(result)


def _pair_summary(p: dict, lang: str = "ko") -> dict:
    es = p.get("energy_signature", {})
    dom = es.get("dominant") or []
    elem_char = dom[0] if dom else "BALANCED"
    
    ELEM_MAP = {
        "水": {"ko": "물", "en": "Water", "ja": "水", "zh_cn": "水", "es": "Agua"},
        "木": {"ko": "나무", "en": "Wood", "ja": "木", "zh_cn": "木", "es": "Madera"},
        "火": {"ko": "불", "en": "Fire", "ja": "火", "zh_cn": "火", "es": "Fuego"},
        "土": {"ko": "흙", "en": "Earth", "ja": "土", "zh_cn": "土", "es": "Tierra"},
        "金": {"ko": "쇠", "en": "Metal", "ja": "金", "zh_cn": "金", "es": "Metal"},
        "BALANCED": {"ko": "균형", "en": "Balanced", "ja": "バランス", "zh_cn": "平衡", "es": "Equilibrado"}
    }
    elem_label = ELEM_MAP.get(elem_char, {}).get(lang, elem_char)
    
    ARCH_MAP = {
        "THE_CREATOR": {"ko": "창조자", "en": "The Creator", "ja": "創造者", "zh_cn": "创造者", "es": "El Creador"},
        "THE_WARRIOR": {"ko": "전사", "en": "The Warrior", "ja": "戦士", "zh_cn": "战士", "es": "El Guerrero"},
        "THE_SAGE": {"ko": "현자", "en": "The Sage", "ja": "賢者", "zh_cn": "贤者", "es": "El Sabio"},
        "THE_LOVER": {"ko": "연인", "en": "The Lover", "ja": "恋人", "zh_cn": "恋人", "es": "El Amante"},
        "THE_RULER": {"ko": "통치자", "en": "The Ruler", "ja": "支配者", "zh_cn": "统治者", "es": "El Gobernante"},
    }
    arch_key = p["archetype"]["key"]
    arch_label = ARCH_MAP.get(arch_key, {}).get(lang, arch_key)
    
    INTENSITY_MAP = {
        "STRONG": {"ko": "강한", "en": "Strong", "ja": "強い", "zh_cn": "强", "es": "Fuerte"},
        "BALANCED": {"ko": "균형 잡힌", "en": "Balanced", "ja": "バランスの取れた", "zh_cn": "平衡的", "es": "Equilibrado"},
        "GENTLE": {"ko": "부드러운", "en": "Gentle", "ja": "穏やかな", "zh_cn": "柔和的", "es": "Suave"},
    }
    int_raw = p["archetype"].get("intensity", "BALANCED")
    int_label = INTENSITY_MAP.get(int_raw, {}).get(lang, int_raw)

    return {
        "archetype": arch_key,
        "archetype_label": arch_label,
        "element": elem_char,
        "element_label": elem_label,
        "intensity": int_raw,
        "intensity_label": int_label,
    }


@router.post("/compatibility", response_model=CompatibilityResponse)
def api_compatibility(
    payload: CompatibilityRequest,
    user: dict = Depends(get_current_user),
):
    if not _can_access_compat(user):
        raise HTTPException(
            status_code=403,
            detail=(
                "This feature requires a 'compatibility' add-on or premium tier. "
                "Purchase from the app's add-ons screen."
            ),
        )

    try:
        pa = _build_profile(payload.person_a)
        pb = _build_profile(payload.person_b)
    except (DSTAmbiguousError, DSTGapError) as e:
        raise HTTPException(status_code=400, detail=format_dst_error(payload.lang, e))
    except (ValueError, TypeError) as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception:
        logger.exception("Compatibility calculation failed")
        raise HTTPException(status_code=500, detail="Calculation error.")

    compat = compute_compatibility(pa, pb)
    response = write_compatibility(compat, lang=payload.lang, relationship_type=payload.relationship_type)
    response["pair"] = {
        "a": _pair_summary(pa, payload.lang),
        "b": _pair_summary(pb, payload.lang),
    }
    return {"compatibility": response}
